public sealed record UnionShape(IShape A, IShape B) : IShape
{
    public T Process<T>(IShapeProcessor<T> p) =>
        p is IUnionShapeProcessor<T> up            // capability test at the element
            ? up.ForUnionShape(this)
            : throw new NotSupportedException($"no handler for {nameof(UnionShape)}");
}
public class UnionContainsPoint(Point p) : ContainsPoint(p), IUnionShapeProcessor<bool>
{
    protected override ContainsPoint MakeContainsPoint(Point q) => new UnionContainsPoint(q);
    public bool ForUnionShape(UnionShape u) => u.A.Process(this) || u.B.Process(this);
}

