public interface IShapeVisitor                      // v1: already implemented by clients
{
    bool VisitCircle(Circle c);
    bool VisitUnknown(IShape s);                    // the default case
}

public interface IShapeVisitor2 : IShapeVisitor     // v2: new element kind, non-breaking
{
    bool VisitUnion(UnionShape u) => VisitUnknown(u); // default member: old clients keep compiling
}
